PRAGMA application_id=1313230897;
CREATE TABLE repository_meta(id INTEGER PRIMARY KEY CHECK(id=1),repository_id TEXT NOT NULL UNIQUE,channel TEXT NOT NULL CHECK(channel IN ('qa','production')),bootstrap_sha256 TEXT NOT NULL,generation INTEGER NOT NULL CHECK(generation BETWEEN 0 AND 9007199254740991),head TEXT NOT NULL,max_utc TEXT NOT NULL) STRICT;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY CHECK(version=1),sha256 TEXT NOT NULL) STRICT;
CREATE TABLE operations(id TEXT PRIMARY KEY,seq INTEGER NOT NULL UNIQUE CHECK(seq BETWEEN 1 AND 50000),request_sha256 TEXT NOT NULL,accepted_at TEXT NOT NULL,body BLOB NOT NULL CHECK(length(body) BETWEEN 1 AND 8192),previous_hash TEXT NOT NULL,entry_hash TEXT NOT NULL UNIQUE,receipt BLOB NOT NULL CHECK(length(receipt) BETWEEN 1 AND 8192)) STRICT;
CREATE TABLE content_objects(scheme TEXT NOT NULL,sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 2097152),PRIMARY KEY(scheme,sha256)) STRICT;
CREATE TABLE signed_payloads(sha256 TEXT PRIMARY KEY CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),content_scheme TEXT NOT NULL,content_sha256 TEXT NOT NULL,bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 2097152),FOREIGN KEY(content_scheme,content_sha256) REFERENCES content_objects(scheme,sha256)) STRICT;
CREATE TABLE containers(sha256 TEXT PRIMARY KEY CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),payload_sha256 TEXT NOT NULL REFERENCES signed_payloads(sha256),bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 2097152)) STRICT;
CREATE TABLE trust_documents(sha256 TEXT PRIMARY KEY,bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 262144)) STRICT;
CREATE TABLE trust_episodes(seq INTEGER PRIMARY KEY REFERENCES operations(seq),root_version INTEGER NOT NULL,epoch INTEGER NOT NULL,payload_sha256 TEXT NOT NULL) STRICT;
CREATE TABLE trust_episode_documents(episode INTEGER NOT NULL REFERENCES trust_episodes(seq),position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 15),document TEXT NOT NULL REFERENCES trust_documents(sha256),PRIMARY KEY(episode,position)) STRICT;
CREATE TABLE trust_head(id INTEGER PRIMARY KEY CHECK(id=1),episode INTEGER NOT NULL REFERENCES trust_episodes(seq),root_version INTEGER NOT NULL,epoch INTEGER NOT NULL,payload_sha256 TEXT NOT NULL) STRICT;
CREATE TABLE delegations(key_id TEXT PRIMARY KEY,bytes BLOB NOT NULL) STRICT;
CREATE TABLE revoked_keys(key_id TEXT PRIMARY KEY) STRICT;
CREATE TABLE withdrawn_payloads(sha256 TEXT PRIMARY KEY) STRICT;
CREATE TABLE signed_revision_floors(stream TEXT NOT NULL,exercise INTEGER NOT NULL,profile TEXT NOT NULL,epoch INTEGER NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(stream,exercise,profile)) STRICT;
CREATE TABLE publications(channel TEXT NOT NULL,stream TEXT NOT NULL,exercise INTEGER NOT NULL,profile TEXT NOT NULL,epoch INTEGER NOT NULL CHECK(epoch BETWEEN 1 AND 9007199254740991),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),payload_sha256 TEXT NOT NULL REFERENCES signed_payloads(sha256),PRIMARY KEY(channel,stream,exercise,profile,epoch,revision)) STRICT;
CREATE TABLE publication_containers(payload_sha256 TEXT NOT NULL REFERENCES signed_payloads(sha256),container_sha256 TEXT NOT NULL UNIQUE REFERENCES containers(sha256),PRIMARY KEY(payload_sha256,container_sha256)) STRICT;
CREATE TABLE verification_records(operation TEXT NOT NULL REFERENCES operations(id),capability TEXT NOT NULL CHECK(capability IN ('direct','inverse')),container_sha256 TEXT NOT NULL REFERENCES containers(sha256),trust_episode INTEGER NOT NULL REFERENCES trust_episodes(seq),report BLOB NOT NULL,PRIMARY KEY(operation,capability)) STRICT;
CREATE TABLE installations(id TEXT PRIMARY KEY,container_sha256 TEXT NOT NULL UNIQUE REFERENCES containers(sha256),operation TEXT NOT NULL REFERENCES operations(id)) STRICT;
CREATE TABLE admissions(id TEXT PRIMARY KEY,installation TEXT NOT NULL REFERENCES installations(id),operation TEXT NOT NULL REFERENCES operations(id),state TEXT NOT NULL CHECK(state='recorded-not-executable')) STRICT;
CREATE TABLE accepted_heads(channel TEXT NOT NULL,stream TEXT NOT NULL,exercise INTEGER NOT NULL,profile TEXT NOT NULL,epoch INTEGER NOT NULL,revision INTEGER NOT NULL,payload_sha256 TEXT NOT NULL REFERENCES signed_payloads(sha256),operation TEXT NOT NULL REFERENCES operations(id),PRIMARY KEY(channel,stream,exercise,profile)) STRICT;
CREATE TABLE rollback_documents(sha256 TEXT PRIMARY KEY,bytes BLOB NOT NULL CHECK(length(bytes) BETWEEN 1 AND 262144),operation TEXT NOT NULL REFERENCES operations(id)) STRICT;
CREATE TABLE selection_events(id TEXT PRIMARY KEY,operation TEXT NOT NULL UNIQUE REFERENCES operations(id),installation TEXT NOT NULL REFERENCES installations(id),exception_nonce TEXT UNIQUE REFERENCES rollback_uses(nonce) DEFERRABLE INITIALLY DEFERRED,UNIQUE(id,exception_nonce)) STRICT;
CREATE TABLE rollback_uses(nonce TEXT PRIMARY KEY,grant_sha256 TEXT NOT NULL REFERENCES rollback_documents(sha256),selection_event TEXT NOT NULL UNIQUE,FOREIGN KEY(selection_event,nonce) REFERENCES selection_events(id,exception_nonce) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE recovery_events(id TEXT PRIMARY KEY,purpose TEXT NOT NULL,manifest_sha256 TEXT NOT NULL) STRICT;
CREATE INDEX installations_container ON installations(container_sha256);
CREATE INDEX operations_time ON operations(accepted_at,seq);
CREATE INDEX publications_payload ON publications(payload_sha256);
CREATE TRIGGER content_no_update BEFORE UPDATE ON content_objects BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER content_no_delete BEFORE DELETE ON content_objects BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER payload_no_update BEFORE UPDATE ON signed_payloads BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER payload_no_delete BEFORE DELETE ON signed_payloads BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER envelope_no_update BEFORE UPDATE ON containers BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER envelope_no_delete BEFORE DELETE ON containers BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER operation_no_update BEFORE UPDATE ON operations BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER operation_no_delete BEFORE DELETE ON operations BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER trust_no_update BEFORE UPDATE ON trust_documents BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER trust_no_delete BEFORE DELETE ON trust_documents BEGIN SELECT RAISE(ABORT,'immutable'); END;
PRAGMA user_version=1;
